class Kelas {
  constructor(nama, siswa) {
    this.nama = nama;
    this.siswa = siswa;
  }
  daftarHadir() {
    return this.siswa.map((s) => `${s} - ${this.nama}`);
  }
}
const k = new Kelas("XI IPA", ["Rina", "Budi"]);
const hasil = k.daftarHadir();
console.log(hasil[0]);
console.log(hasil.length);

