class Kasir {
  constructor(pajak) {
    this.pajak = pajak;
  }
  hargaPlusPajak(harga) {
    return harga + (harga * this.pajak) / 100;
  }
  prosesSemua(daftar) {
    return daftar.map(this.hargaPlusPajak);
  }
}
const kasir = new Kasir(10);
console.log(kasir.prosesSemua([10000, 25000, 50000]).join(", "));

